properties.tools:
[
  {
    "name": "graph_schema",
    "description": "The schema of the agent's knowledge graph: every node label with its count and its property names and types, and every relationship type with its count and the labels it connects. Read it before writing a query or an ingest, so labels, types and property names match what the graph holds.",
    "input_schema": {
      "type": "object",
      "properties": {},
      "required": [],
      "additionalProperties": false
    },
    "route": "graph.schema"
  },
  {
    "name": "graph_query",
    "description": "Run a read-only openCypher query against the agent's knowledge graph and return its rows. Pass values as parameters ($name in the query, the value under that name in parameters) instead of writing them into the query. A node comes back as {id, labels, properties}, a relationship as {id, type, start, end, properties}, a path as a list of them. Rows are capped: narrow the query with WHERE and LIMIT when the result was cut. A query that writes (CREATE, MERGE, SET, DELETE, REMOVE, DROP, LOAD CSV) is refused - use graph_write or graph_ingest.",
    "input_schema": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string",
          "description": "The openCypher query, read-only, with $parameters."
        },
        "parameters": {
          "type": "object",
          "description": "The values the query's $parameters take."
        }
      },
      "required": [
        "query"
      ],
      "additionalProperties": false
    },
    "route": "graph.query"
  }
]
